  grammar:[
    {track:'Foundation',title:'Present Simple',rule:'Use the base verb for routines, repeated actions and facts.',example:'I work in marketing, and our team meets every Monday.',task:'Describe your usual workday in three sentences.',quiz:['She ___ in the HR department.','works','work']},
    {track:'Foundation',title:'Present Continuous',rule:'Use am/is/are + verb-ing for actions happening now or temporary situations.',example:'I am working from home this week.',task:'Say what you are doing today.',quiz:['We ___ a new campaign this month.','are launching','launch']},
    {track:'Foundation',title:'Past Simple',rule:'Use the past form for a finished action at a finished time.',example:'I attended a job interview yesterday.',task:'Explain what happened at work yesterday.',quiz:['The manager ___ the proposal last night.','approved','has approved']},
    {track:'Foundation',title:'Past Continuous',rule:'Use was/were + verb-ing for an action in progress in the past.',example:'I was presenting when the internet stopped working.',task:'Describe an interruption during your day.',quiz:['They ___ the budget when I arrived.','were discussing','discussed']},
    {track:'Foundation',title:'Present Perfect',rule:'Use have/has + past participle for experience or a past result connected to now.',example:'I have completed three marketing projects this month.',task:'Talk about two things you have achieved recently.',quiz:['HR ___ the interview date yet.','has not confirmed','did not confirm yesterday']},
    {track:'Planning',title:'Will vs. going to',rule:'Use going to for plans and will for decisions, promises or predictions.',example:'I’m going to update my CV. I’ll send it tonight.',task:'Share one plan and one promise.',quiz:['I ___ call you back in five minutes.','will','am going']},
    {track:'Planning',title:'First Conditional',rule:'Use if + present, will/can + base verb for a real future possibility.',example:'If the team approves the idea, we will launch it next week.',task:'Make two sentences about possible work results.',quiz:['If I get the job, I ___ next month.','will start','start']},
    {track:'Planning',title:'Second Conditional',rule:'Use if + past, would + base verb for imaginary or unlikely situations.',example:'If I managed the company, I would offer flexible hours.',task:'Say what you would change at work.',quiz:['If we had more time, we ___ the campaign.','would improve','will improve']},
    {track:'Professional',title:'Modal verbs',rule:'Use can, could, should, must and might + base verb.',example:'Could you send the report? We might need it today.',task:'Make one request, one suggestion and one possibility.',quiz:['You ___ prepare before an interview.','should','should to']},
    {track:'Professional',title:'Polite requests',rule:'Use Could you…?, Would you mind…? and Would it be possible…? to sound professional.',example:'Would it be possible to move the meeting to Thursday?',task:'Rewrite two direct commands politely.',quiz:['___ sharing the updated policy?','Would you mind','Do you mind to']},
    {track:'Professional',title:'Passive Voice',rule:'Use be + past participle when the action or result is more important than the person.',example:'The final decision will be announced by HR tomorrow.',task:'Describe a company process in the passive.',quiz:['The invoices ___ every month.','are reviewed','review']},
    {track:'Professional',title:'Reported Speech',rule:'Use said that, told me that, or asked us to when reporting another person’s words.',example:'The manager said that the deadline had changed.',task:'Report three comments from a meeting.',quiz:['She asked me ___ the file again.','to send','send']},
    {track:'Professional',title:'Relative Clauses',rule:'Use who for people and which/that for things to add identifying information.',example:'The candidate who called yesterday has strong experience.',task:'Describe a person and a product using relative clauses.',quiz:['The campaign ___ performed best was the simplest.','that','who']},
    {track:'Professional',title:'Comparatives',rule:'Use -er or more + adjective + than to compare.',example:'This strategy is more effective than the previous one.',task:'Compare two jobs, products or ideas.',quiz:['The new process is ___ than the old one.','more efficient','efficienter']},
    {track:'Natural Speech',title:'Question forms',rule:'Put the auxiliary before the subject: Do you…? Have you…? What did…?',example:'How long have you worked at this company?',task:'Ask five natural questions for a new colleague.',quiz:['Where ___ your last job?','was','did be']},
    {track:'Natural Speech',title:'Articles: a, an, the',rule:'Use a/an for one non-specific thing and the for something specific or already known.',example:'I had an interview with the marketing director.',task:'Describe an office using a, an and the.',quiz:['She is ___ HR specialist.','an','a']},
    {track:'Natural Speech',title:'Countable & uncountable',rule:'Use many/few with countable nouns and much/little with uncountable nouns.',example:'We do not have much time, but we have a few good options.',task:'Talk about your time, tasks and information.',quiz:['We need ___ more information.','a little','a few']},
    {track:'Natural Speech',title:'Gerunds & infinitives',rule:'Some verbs take -ing; others take to + verb.',example:'I enjoy learning English, and I want to speak more naturally.',task:'Use enjoy, avoid, want and decide.',quiz:['We agreed ___ the meeting.','to postpone','postponing']},
    {track:'Natural Speech',title:'Linking ideas',rule:'Use because, although, however and therefore to connect ideas clearly.',example:'The role is challenging; however, it offers good career growth.',task:'Explain a decision using three linking words.',quiz:['The campaign was simple; ___, it was effective.','however','because']},
    {track:'Natural Speech',title:'Used to',rule:'Use used to + base verb for past habits or states that are no longer true.',example:'I used to feel nervous in meetings, but now I speak confidently.',task:'Describe two things that changed in your life.',quiz:['I ___ work at a small agency.','used to','use to']},
    {track:'Advanced',title:'Present Perfect Continuous',rule:'Use have/has been + verb-ing to emphasize duration until now.',example:'I have been preparing for the interview for two weeks.',task:'Describe three ongoing efforts.',quiz:['She ___ with the company since June.','has been working','is working']},
    {track:'Advanced',title:'Third Conditional',rule:'Use if + had + past participle, would have + past participle for an unreal past.',example:'If we had tested the page, we would have found the error earlier.',task:'Reflect on a past project or decision.',quiz:['If I had known, I ___ earlier.','would have applied','would apply']},
    {track:'Advanced',title:'Softening opinions',rule:'Use seems, tends to, might, slightly and I would suggest to sound diplomatic.',example:'The message seems slightly unclear; I would suggest shortening it.',task:'Soften three direct pieces of feedback.',quiz:['The proposal ___ need more detail.','might','must definitely']},
    {track:'Advanced',title:'Emphasis & cleft sentences',rule:'Use What…is or It is…that to emphasize important information.',example:'What customers value most is a quick response.',task:'Emphasize two important business ideas.',quiz:['___ we need is a clearer plan.','What','Which']}
  ],
