SERAG_ENGLISH_V9.vocabulary.push(...[["revision", "تعديل على نسخة موجودة", "Creative", "The client requested one final revision.", "formal"], ["deliverable", "ملف أو نتيجة مطلوب تسليمها", "Creative", "The main deliverable is a thirty-second video.", "formal"], ["rough cut", "نسخة مونتاج أولية", "Creative", "I will send the rough cut tomorrow.", "neutral"], ["feedback round", "جولة ملاحظات", "Creative", "The project includes two feedback rounds.", "formal"], ["aspect ratio", "نسبة أبعاد الصورة", "Creative", "Which aspect ratio do you need for this video?", "formal"], ["approval", "موافقة", "Work & Office", "We need written approval before exporting.", "formal"], ["clarify", "يوضح", "Work & Office", "Could you clarify the main message?", "formal"], ["scope", "نطاق العمل", "Creative", "Adding another video would change the scope.", "formal"], ["estimate", "تقدير", "Work & Office", "I can send a time estimate this afternoon.", "formal"], ["backup", "نسخة احتياطية", "Creative", "Keep a backup of the project files.", "neutral"], ["readable", "سهل القراءة", "Creative", "The text must be readable on a phone.", "neutral"], ["consistent", "متناسق", "Creative", "Keep the lighting consistent across the scenes.", "formal"], ["crop", "يقص أطراف الصورة", "Creative", "Please crop the image to a square.", "neutral"], ["raw footage", "لقطات الفيديو الخام قبل المونتاج", "Creative", "The raw footage is ready for editing.", "neutral"], ["pick up", "يتعلم بالممارسة أو يلتقط", "Phrasal Verbs", "I picked up a few useful phrases from the video.", "natural"], ["work out", "يجد حلًا", "Phrasal Verbs", "We can work out a better schedule.", "natural"], ["get back to", "يرد على شخص لاحقًا", "Phrasal Verbs", "I will get back to you after the meeting.", "natural"], ["get aligned", "نتفق على الاتجاه أو الفهم نفسه", "Idioms", "Let’s get aligned on the main message before the review.", "natural"], ["that works for me", "هذا مناسب لي", "Slang & Natural", "Friday afternoon? That works for me.", "natural"], ["take your time", "خد وقتك", "Everyday", "Take your time and read the instructions.", "natural"]]);
SERAG_ENGLISH_V9.articles.push(...[{"title": "A Clear Brief Saves Time", "level": "B1", "topic": "Creative work", "text": "Before opening a design app, Maya asks her client three questions. Who will see this post? What should they understand? What should they do next? The client first asks for something modern, but that description is too general. After a short discussion, they agree on one message and a clear deadline. Maya writes the agreed details in a brief and sends it for approval. When the client later suggests a different direction, they compare it with the brief. This keeps the conversation focused and helps both people understand which changes affect the original scope.", "question": "How does the brief help when the client suggests a new direction?", "answer": "It gives them agreed details to compare the new direction with.", "words": [["brief", "ملخص متطلبات المشروع"], ["approval", "موافقة"], ["scope", "نطاق العمل"]], "checks": [["What does Maya do before designing?", ["She asks about the audience and message.", "She exports the final file.", "She buys a new app."], 0, "هي بتحدد الجمهور والرسالة الأول، قبل تنفيذ التصميم."], ["Why is “modern” not enough?", ["It describes an exact size.", "It is too general.", "It gives a clear deadline."], 1, "كلمة modern عامة ومش بتوضح المطلوب بالتحديد."]]}, {"title": "Sending a Rough Cut", "level": "B1", "topic": "Video editing", "text": "Omar is editing a short restaurant video. Instead of polishing every transition immediately, he sends a rough cut first. This early version shows the order of the shots, the main story and the approximate timing. He explains that the colours and audio are not final. He asks the client to comment on the message and pacing. The client wants the food close-up to appear earlier. Omar can make this change quickly because he has not finished the detailed effects yet. Once the structure is approved, he adjusts the sound, colour and titles, then checks the final video on a phone.", "question": "Why can Omar change the shot order quickly?", "answer": "He has not finished the detailed effects yet.", "words": [["rough cut", "نسخة مونتاج أولية"], ["pacing", "إيقاع الفيديو"], ["close-up", "لقطة قريبة"]], "checks": [["What should the client review first?", ["The final colour.", "The export filename.", "The message and pacing."], 2, "النسخة الأولية لمراجعة الفكرة وإيقاع المشاهد."], ["When does Omar finish the sound and titles?", ["After the structure is approved.", "Before arranging the shots.", "Before receiving the footage."], 0, "بيخلص التفاصيل بعد الموافقة على ترتيب وبناء الفيديو."]]}, {"title": "Asking for More Time", "level": "B1", "topic": "Communication", "text": "A deadline is approaching, but Salma is still waiting for the product photos. She does not stay silent until the last minute. She sends a short update explaining what is complete, what is missing and how the missing files affect delivery. She offers two options: deliver the text layouts on the original date, or deliver the complete campaign two days after receiving the photos. Her message is polite and specific. The client chooses the second option and confirms it in writing. A clear update cannot remove every delay, but it allows people to make an informed decision.", "question": "What two options does Salma offer?", "answer": "Text layouts on the original date, or the complete campaign two days after receiving the photos.", "words": [["approaching", "بيقترب"], ["delivery", "التسليم"], ["informed decision", "قرار مبني على معلومات"]], "checks": [["Why is the work delayed?", ["The client lost the brief.", "The product photos are missing.", "The app is unavailable."], 1, "سلمى مستنية صور المنتجات."], ["What makes her update useful?", ["It gives specific options.", "It hides the delay.", "It blames the client."], 0, "الرسالة بتوضح الوضع وبتدي بدائل محددة."]]}, {"title": "Learning One Phrase Well", "level": "B1", "topic": "Everyday English", "text": "Youssef used to collect long vocabulary lists, but he rarely used the words in conversation. Now he chooses one useful phrase each day. First, he reads an example and checks the meaning. Then he makes a sentence about his own life. He says it aloud without looking at the screen. The next day, he tries to remember it before checking his notes. If he forgets, he studies the example again. At the end of the week, he uses several phrases in a short voice recording. His goal is not to collect the most words. It is to remember useful language when he needs it.", "question": "What does Youssef do before checking his notes the next day?", "answer": "He tries to remember the phrase.", "words": [["aloud", "بصوت مسموع"], ["phrase", "عبارة"], ["rarely", "نادرًا"]], "checks": [["What changed in his learning?", ["He stopped using examples.", "He focused on using fewer phrases well.", "He only reads translations."], 1, "بقى بيركز على استخدام عبارات قليلة بشكل فعلي."], ["What does he do at the end of the week?", ["Deletes the notes.", "Buys a textbook.", "Records himself using several phrases."], 2, "بيجمع العبارات في تسجيل صوتي قصير."]]}]);
SERAG_ENGLISH_V9.speaking.push(...[{"type": "Creative", "prompt": "Explain what is included in a video project and what would count as extra work.", "hint": "وضح التسليمات والتعديلات الإضافية بأدب", "starter": "This project includes… Additional changes would…"}, {"type": "Creative", "prompt": "Ask a client for clear feedback on a rough cut.", "hint": "اطلب ملاحظات على الفكرة والإيقاع", "starter": "Could you focus on…? The colour and sound are not final yet."}]);


